return ['domain'=>'lingua-forge','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10 >= 2 && n%10<=4 &&(n%100<10||n%100 >= 20)? 1 : 2);','language'=>'ru_RU','project-id-version'=>'Lingua Forge 2.1.0','pot-creation-date'=>'2026-07-29T14:57:34+00:00','po-revision-date'=>'2026-07-05 23:00+0000','x-generator'=>'Loco https://localise.biz/','messages'=>['Lingua Forge'=>'Лингва Фордж','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','Multilingual routing, complete multilingual SEO (hreflang, Open Graph, Schema.org, sitemap), and AI content tools for WordPress. Language detection, URL routing, translation, content generation, and a full SEO layer — no companion plugin required.'=>'Многоязычная маршрутизация, полноценное многоязычное SEO (hreflang, Open Graph, Schema.org, карта сайта), и инструменты AI для контента для WordPress. Обнаружение языка, маршрутизация URL, перевод, создание контента и полноценный SEO-слой — без необходимости дополнительного плагина.','Uli Hake'=>'Ули Хаке','https://lingua-forge.com'=>'https://lingua-forge.com','Translate'=>'Перевести','Lingua Forge — Quick Translate'=>'Лингва Фордж — Быстрый перевод','Informative'=>'Информативный','Persuasive'=>'Убедительный','Storytelling'=>'Рассказывание историй','Technical'=>'Технический','Conversational'=>'Разговорный','Translate missing'=>'Перевод отсутствует','%d comment translation created.'=>'%d переведенный комментарий создан.' . "\0" . '%d переведенных комментариев создано.' . "\0" . '%d переведенных комментариев создано.','%d pair could not be translated yet (e.g. a nested reply waiting on its parent, or a language currently in cooldown after repeated failures).'=>'%d пар еще не могут быть переведены (например, вложенный ответ ожидает своего родителя или язык в данный момент на паузе после нескольких неудач).' . "\0" . '%d пар еще не могут быть переведены (например, вложенные ответы ожидают своего родителя или язык в данный момент на паузе после нес